GLOSSARY = {
    "Slope β": "Expected fitted change in Y for a one-unit difference in X. Its unit is Y units per X unit.",
    "Intercept α": "Fitted Y at X=0. It may lack a meaningful interpretation when zero is outside the observed X range.",
    "Residual": "Observed Y minus fitted Y. Residuals estimate unobserved errors; they are not the actual population errors.",
    "R²": "1 − SSE/SST: fraction of sample variation in Y around its mean accounted for by the fitted line with an intercept.",
    "Adjusted R²": "1 − (1−R²)(n−1)/(n−2). Penalizes the fitted predictor; it can be negative.",
    "p-value": "Under the null and the test's assumptions, the probability of a result at least as extreme as observed. Not the probability that the null is true.",
    "t test": "Classical coefficient estimate divided by its standard error, compared with a t distribution with n−2 degrees of freedom.",
    "F test": "Classical overall regression test: H₀: β=0. F=(SSR/1)/(SSE/(n−2)). In SLR with an intercept, F=t_slope² and the two p-values agree.",
    "Confidence interval": "A procedure that covers the population quantity in the stated fraction of repeated samples under the assumptions. Not a posterior probability about the fixed parameter.",
    "Mean response interval": "Uncertainty about E(Y|X=x₀), the average response at a given X.",
    "Prediction interval": "Uncertainty about one new Y at X=x₀. It includes new-observation noise and is wider than the mean confidence interval.",
    "Residual standard error": "sqrt(SSE/(n−2)); estimated error standard deviation in Y units. Distinct from in-sample RMSE sqrt(SSE/n).",
    "Leverage": "hᵢ=1/n+(xᵢ−x̄)²/Sxx; distance in the X design. High leverage is not itself an error.",
    "Cook distance": "Combines residual size and leverage to screen observations that may substantially change the fitted coefficients.",
    "PRESS / LOOCV": "PRESS=Σ[eᵢ/(1−hᵢ)]²; leave-one-out prediction error. Not time-series forecasting validation because future rows can inform past predictions.",
    "Exogeneity": "E(ε|X)=0. This substantive assumption cannot be established from a zero sample residual–X correlation, which OLS imposes algebraically.",
}
